<script>
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let cfg={orkey:""};
try{cfg={...cfg,...JSON.parse(localStorage.getItem("sim-cfg")||"{}")};
  if(!cfg.orkey){const ag=JSON.parse(localStorage.getItem("ag-cfg")||"{}");if(ag.orkey)cfg.orkey=ag.orkey;}}catch(e){}
// clave local (solo existe en la máquina de Daniel; gitignoreada)
if(!cfg.orkey)fetch("../assets/local_keys.json").then(r=>r.json())
  .then(d=>{if(d.openrouter)cfg.orkey=d.openrouter}).catch(()=>{});
$("#gear").onclick=e=>{e.stopPropagation();const c=$("#cfg");c.style.display=c.style.display==="none"?"block":"none"};
document.addEventListener("click",e=>{if(!$("#cfg").contains(e.target)&&e.target.id!=="gear")$("#cfg").style.display="none"});
$("#c-orkey").onchange=e=>{cfg.orkey=e.target.value.trim();try{localStorage.setItem("sim-cfg",JSON.stringify(cfg))}catch(_){}};

/* ── PACER de /api/opina: los 30 asistentes del evento salen por el MISMO IP ──
   una tertulia de 8 voces dispara ~12 requests en ráfaga (contexto ×2 + Jev +
   8 voces + conclusión) y el rate limit de 30/min devuelve 429 a todos: la demo
   se cae completa. Reglas: UNA sola petición en vuelo por navegador, separación
   mínima con JITTER (los 30 navegadores no salen sincronizados) y reintento con
   backoff exponencial + Retry-After cuando el backend ya contestó 429. */
/* semáforo de 3 en vuelo (5 búsquedas paralelas caben; 30 usuarios no revientan el IP) */
let EN_VUELO=0,T_OPINA=0,GAP=200;const ESPERAN=[];
const dormir=ms=>new Promise(r=>setTimeout(r,ms));
async function encolar(fn){
  while(EN_VUELO>=3)await new Promise(r=>ESPERAN.push(r));
  EN_VUELO++;
  try{return await fn();}
  finally{EN_VUELO--;ESPERAN.shift()?.();}
}
const _fetch=window.fetch.bind(window);
window.fetch=function(u,o){
  if(String(u).indexOf("/api/opina")<0)return _fetch(u,o);
  return encolar(async()=>{
    let r;
    for(let intento=0;intento<5;intento++){
      const espera=Math.max(0,T_OPINA+GAP+Math.random()*GAP-Date.now());
      if(espera)await dormir(espera);
      r=await _fetch(u,o);
      T_OPINA=Date.now();
      if(r.status!==429){GAP=Math.max(180,Math.round(GAP*0.85));return r;}
      const ra=Number(r.headers.get("Retry-After"))*1000||0;
      GAP=Math.min(8000,Math.max(GAP*3,ra));   // el IP está saturado: espaciar de más
      await dormir(GAP+Math.random()*GAP);
    }
    return r;
  });
};

/* controles de la deliberación */
let CONV={paused:false,stop:false,start:0};
let RUN=0;
const TW=new Set();   // intervals vivos del typewriter (texto y retrato): abortarCorrida los apaga
/* aborta cualquier corrida viva: invalida su token, suelta la pausa, corta sus typewriters y devuelve los controles */
function abortarCorrida(){RUN++;CONV.stop=true;CONV.paused=false;
  TW.forEach(iv=>clearInterval(iv));TW.clear();
  $("#ctrl").style.display="none";$("#reloj").textContent="";
  $("#btnpausa").textContent="⏸ PAUSAR";$("#btnpausa").classList.remove("pausa");
  const b=$("#qbar button");if(b)b.disabled=false;}  // token de corrida: solo la última pregunta puede escribir en pantalla
$("#btnpausa").onclick=()=>{CONV.paused=!CONV.paused;
  $("#btnpausa").textContent=CONV.paused?"▶ SEGUIR":"⏸ PAUSAR";
  $("#btnpausa").classList.toggle("pausa",CONV.paused);};
$("#btnfin").onclick=()=>{CONV.stop=true;abortarCorrida();};  // stop en la corrida viva + teardown (typewriters, controles, botón)
setInterval(()=>{if($("#ctrl").style.display!=="none"&&CONV.start){
  const s=Math.round((Date.now()-CONV.start)/1000);
  $("#reloj").textContent=(CONV.paused?"⏸ ":"")+Math.floor(s/60)+":"+String(s%60).padStart(2,"0");
}},1000);

/* ═══ MODO PAÍS: una pregunta, 33 mesas — el mapa se pinta con las conclusiones ═══ */
let GEO=null,PAIS={q:null,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
async function pais(q){
  OPC=opcionesDe(q);
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){
    $("#resps").innerHTML="<div class='hint'>no cargó el mapa</div>";return;}}
  PAIS={q,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
  CONV={paused:false,stop:false,start:Date.now()};  // corrida fresca: sin esto, el stop de abortarCorrida() mata cada mesa al nacer
  $("#ctrl").style.display="flex";  // en país también hay ■ CERRAR: corta las mesas en vuelo
  DECIDIDO={}; paintNav();
  $("#tally").innerHTML="";
  $("#maptag").textContent="el país responde";
  $("#resps").innerHTML=`
    <div style="color:var(--dim);padding:2px 2px 8px">
      <b class="pxf" style="font-size:10px;color:var(--work)">EL PAÍS RESPONDE</b> ${esc(q)}</div>
    <div id="mesa"><div class="hint">◂ toca un departamento en el mapa<br><br>
      cada territorio arma su mesa de 4, conversa corto y CONCLUYE —
      el mapa se va pintando con los veredictos</div></div>`;
}
async function mesa(cod){
  const el=$("#mesa"),d=MARG[cod],dos=DOS[cod]||{};
  if(!el)return;
  const owner=PAIS,q=PAIS.q;
  if(owner.data?.[cod]&&PAIS===owner){renderMesa(cod,owner.data[cod],el);owner.busy[cod]=false;return;}
  owner.busy??={}; if(owner.busy[cod])return; owner.busy[cod]=true;
  const path=$(`#navmap path[data-cod="${cod}"]`);
  const finMesa=()=>{if(PAIS===owner)owner.busy[cod]=false;};
  if(PAIS!==owner||!document.body.contains(el)){finMesa();return;}
  el.innerHTML=`<div class="ronda">— MESA DE ${esc(d.nombre).toUpperCase()} —</div>`;
  path?.classList.add("hot");
  const sample=RES.filter(r=>r.dpto===cod&&r.edad>=16).sort(()=>Math.random()-.5).slice(0,4);
  el.insertAdjacentHTML("beforeend",`<div id="seats"></div><div id="ticker"><span id="tickertxt">llegan los de ${esc(d.nombre)}…</span></div>`);
  const _seats=el.querySelector("#seats");
  sample.forEach((r,i)=>{const s=document.createElement("div");s.className="seat";
    RESBY[r.id]=r;s.dataset.rid=r.id;s.title="ver ficha DANE";
    s.style.animationDelay=(i*0.13)+"s";
    const cv=document.createElement("canvas");retrato(cv,r.id,r.sexo,r.ocupacion,r.edad);
    s.append(cv);s.insertAdjacentHTML("beforeend",`<span>${esc(r.nombre.split(" ")[0])}, ${r.edad}</span>`);
    s.dataset.rid=r.id;s.title="ver ficha DANE";RESBY[r.id]=r;
    s.setAttribute("role","button");s.setAttribute("tabindex","0");
    _seats.append(s);});
  let ctx=null;
  try{ctx=await contexto(q);}catch(e){}  // sin contexto la mesa sigue: las voces hablan de lo suyo
  if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
  el.querySelector("#ticker")?.remove();
  ctxBox(ctx,el);
  const transcript=[];
  for(let i=0;i<sample.length;i++){
    const r=sample[i],card=bubble(r,i%2===1,el),say=card.querySelector(".say");
    if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
    try{
      const charla=transcript.length?
        "La mesa va así:\n"+transcript.map(t=>`${t.n}: ${t.t}`).join("\n"):"abres tú la mesa";
      const raw=await flash([{role:"system",content:persona(r,dos)+ctxPara(ctx)+`
Mesa de vecinos en ${d.nombre}. El tema es cómo les afecta A USTEDES, en SU territorio. Reacciona a lo dicho (cita por nombre, contradice o apoya), aterriza con tu vida y tu región. 1-2 frases. Cierra con [POSTURA: a_favor|en_contra|depende] — a_favor significa SÍ A LA PREGUNTA LITERAL del tema, no a lo que digan las noticias.`},
        {role:"user",content:`Tema: ${q}\n${charla}\nHabla, ${r.nombre.split(" ")[0]}.`}],160);
      if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
      let [pos,txt]=postura(raw);
      if(!pos)pos=(await clasificarPostura(q,txt))||'';
      if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
      if(!['a_favor','en_contra','depende'].includes(pos))pos='depende';
      typewriter(say,txt);
      card.style.setProperty("--pc",COLORES[pos]);
      transcript.push({n:r.nombre.split(" ")[0],t:txt,p:pos});
    }catch(e){say.classList.remove("thinking");say.textContent="(se quedó callado)";}
  }
  /* la mesa CONCLUYE — nada de conversación eterna */
  let concl="",pos="depende";
  if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
  try{
    const raw=await flash([{role:"system",content:
      `Cierras mesas de conversación. Resume EN QUÉ QUEDÓ esta mesa de ${d.nombre} en 2 frases máximo, con nombres, y da el veredicto del grupo. Cierra con [POSTURA: a_favor|en_contra|depende] (la mayoritaria).`},
      {role:"user",content:`Tema: ${q}\n`+transcript.map(t=>`${t.n} (${t.p}): ${t.t}`).join("\n")}],130,0.5);
    if(CONV.stop||PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
    [pos,concl]=[postura(raw)[0]||mayoria(transcript),postura(raw)[1]];
    if(!['a_favor','en_contra','depende'].includes(pos))pos=mayoria(transcript)||'depende';
  }catch(e){pos=mayoria(transcript);concl="La mesa quedó dividida.";}
  if(PAIS!==owner||!document.body.contains(el)){path?.classList.remove("hot");finMesa();return;}
  el.insertAdjacentHTML("beforeend",
    `<div class="conclu" style="--pc:${COLORES[pos]}"><b>EN QUÉ QUEDÓ ${esc(d.nombre).toUpperCase()}</b>${esc(concl)}</div>`);
  festejo(el);
  selloHumano(q,transcript,el);
  el.scrollTop=1e9;
  path?.classList.remove("hot");
  path?.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[pos]);
  DECIDIDO[cod]=pos; paintNav();
  owner.tally[pos]++;
  guardar("pais",cod,q,{postura:pos,conclusion:concl,
    participantes:sample.map(r=>r.id),intervenciones:transcript.length});
  $("#tally").innerHTML=
    `<div class="tal fav"><b>${owner.tally.a_favor}</b><span>dptos a favor</span></div>
     <div class="tal con"><b>${owner.tally.en_contra}</b><span>dptos en contra</span></div>
     <div class="tal dep"><b>${owner.tally.depende}</b><span>dptos divididos</span></div>`;
  (owner.data??={})[cod]={transcript,concl,pos,ctx,sample:sample.map(r=>r.id)};
  finMesa();
}
/* re-render de una mesa concluida desde sus DATOS (los canvas se redibujan) */
function renderMesa(cod,dat,el){
  const d=MARG[cod];
  el.innerHTML=`<div class="ronda">— MESA DE ${esc(d.nombre).toUpperCase()} —</div>`;
  ctxBox(dat.ctx,el);
  dat.transcript.forEach((tr,i)=>{
    const r=RESBY[dat.sample?.[i]]||RES.find(x=>x.id===dat.sample?.[i]);
    if(!r)return;
    const card=bubble(r,i%2===1,el),say=card.querySelector(".say");
    say.classList.remove("thinking");say.textContent=tr.t;
    card.style.setProperty("--pc",COLORES[tr.p||"depende"]);
  });
  el.insertAdjacentHTML("beforeend",
    `<div class="conclu" style="--pc:${COLORES[dat.pos]}"><b>EN QUÉ QUEDÓ ${esc(d.nombre).toUpperCase()}</b>${esc(dat.concl)}</div>`);
  festejo(el);
  el.scrollTop=1e9;
}
function mayoria(ts){
  const c={a_favor:0,en_contra:0,depende:0};ts.forEach(t=>{if(t.p in c)c[t.p]++});
  const o=Object.entries(c).sort((a,b)=>b[1]-a[1]);
  return o[0][1]===o[1][1]?"depende":o[0][0];
}
/* cada encuesta queda en la base (Supabase) — la memoria del país sintético */
function guardar(modo,dpto,pregunta,resultado){
  try{fetch("https://pwcvskguqyhbhlwnsmmy.supabase.co/rest/v1/sim_encuestas",{
    method:"POST",headers:{apikey:"sb_publishable_1S4AdKr4TJqGWt9LNL_XaQ_OWrCusLw",
    "Content-Type":"application/json"},
    body:JSON.stringify({modo,dpto,pregunta,resultado})}).catch(()=>{});}catch(e){}
}

let RES=[],MARG={},DOS={},VAL={},cur="11";
let SEL=new Set(["11"]);   // territorios elegidos para la muestra (vacío = todo el país)
let DECIDIDO={};  // cod → postura concluida (pinta ambos mapas)

const MODOTXT={
  sondeo:"SONDEO · Todos contestan a la vez. Rápido: cuántos dirían sí, no o depende.",
  tertulia:"TERTULIA · Conversan de a uno, se responden y se contradicen. Hasta 3 minutos o hasta ponerse de acuerdo.",
  pais:"EL PAÍS · Escribes una pregunta y tocas el mapa: cada territorio delibera, concluye y se pinta."};
function selInfo(){
  const el=$("#selinfo"); if(!el)return;
  if(!SEL.size){el.innerHTML=`<b>muestra:</b> toda Colombia (proporcional a población real) — toca el mapa para acotar`;return;}
  el.innerHTML=`<b>muestra:</b> `+[...SEL].map(c=>
    `<span class="chip">${esc(MARG[c]?.nombre||c)}<button type="button" class="chip-x" data-c="${c}" aria-label="Quitar ${esc(MARG[c]?.nombre||c)} de la muestra">×</button></span>`).join("")+
    `<button id="cleartodo" type="button">todo el país</button>`;
  el.querySelectorAll("button.chip-x[data-c]").forEach(b=>b.onclick=()=>{SEL.delete(b.dataset.c);syncSel();});
  const b=el.querySelector("#cleartodo"); if(b)b.onclick=()=>{SEL.clear();syncSel();};
}
function syncSel(){
  if(SEL.size===1)cur=[...SEL][0];
  $("#dptosel").value=SEL.size===1?cur:"CO";
  paintNav();selInfo();render();
}

async function drawNav(){
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){return}}
  $("#navmap").innerHTML=`<div id="maptip"></div><svg viewBox="${GEO.viewBox}" role="group" aria-label="Mapa de Colombia: usa Tab y Enter para elegir territorio">${
    Object.entries(GEO.paths).map(([c,p])=>`<path d="${p}" data-cod="${c}" role="button" tabindex="0" aria-label="${esc(MARG[c]?.nombre||c)}"/>`).join("")}</svg>`;
  const svg=$("#navmap svg");
  function elegir(cod){
    if(!cod)return;
    if(MODO==="pais"&&PAIS.q){cur=cod;SEL=new Set([cod]);$("#dptosel").value=cod;selInfo();paintNav();render();mesa(cod);return;}
    if(SEL.has(cod)&&SEL.size>0)SEL.delete(cod);else SEL.add(cod);
    cur=cod; syncSel();
  }
  svg.addEventListener("click",e=>elegir(e.target.dataset?.cod));
  svg.addEventListener("keydown",e=>{
    const cod=e.target.dataset?.cod;
    if(cod&&(e.key==="Enter"||e.key===" ")){e.preventDefault();elegir(cod);}
  });
  let hovCod=null;
  const estadoDe=cod=>{
    const path=svg.querySelector(`path[data-cod="${cod}"]`);
    if(path?.classList.contains("hot"))return "🟡 deliberando ahora…";
    if(PAIS?.data?.[cod])return "✓ "+(PAIS.data[cod].concl||"").slice(0,70)+"…";
    if(DECIDIDO[cod])return ({a_favor:"quedó a favor",en_contra:"quedó en contra",depende:"quedó dividido"})[DECIDIDO[cod]];
    if(SEL.has(cod))return "en la muestra · click para quitar";
    return "click para sumarlo a la muestra";
  };
  function hoverMapa(cod,ev){
    /* mismo dpto en movimiento: solo se reposiciona el tip, nada de rehacer innerHTML por píxel */
    if(cod===hovCod&&cod&&ev){const tip=$("#maptip"),r=$("#navmap").getBoundingClientRect();
      tip.style.left=Math.min(ev.clientX-r.x+14,r.width-205)+"px";
      tip.style.top=(ev.clientY-r.y+10)+"px";return;}
    if(cod===hovCod&&!ev)return;
    svg.classList.toggle("spot",!!cod);
    svg.querySelectorAll("path.hov").forEach(x=>x.classList.remove("hov"));
    const tip=$("#maptip");
    if(!cod){tip.style.display="none";hovCod=null;
      $("#maplabel").textContent=MARG[cur]?.nombre||"—";return;}
    hovCod=cod;
    svg.querySelector(`path[data-cod="${cod}"]`)?.classList.add("hov");
    const d=MARG[cod],dos=DOS[cod]||{};
    $("#maplabel").textContent=(d?.nombre||cod)+" · "+estadoDe(cod);
    tip.innerHTML=`<b>${esc(d?.nombre||cod)}</b>
      ${d?.poblacion?(d.poblacion/1e6).toFixed(2).replace(".",",")+" M hab · ":""}200 residentes
      ${dos.apodo_gentilicio?`<br><span style="color:var(--faint)">${esc(dos.apodo_gentilicio.split("·")[0].split(",")[0])}</span>`:""}
      <br><span class="st">${esc(estadoDe(cod))}</span>`;
    if(ev){const r=$("#navmap").getBoundingClientRect();
      tip.style.left=Math.min(ev.clientX-r.x+14,r.width-205)+"px";
      tip.style.top=(ev.clientY-r.y+10)+"px";}
    tip.style.display="block";
  }
  window.hoverMapa=hoverMapa;
  svg.addEventListener("mousemove",e=>hoverMapa(e.target.dataset?.cod||null,e));
  svg.addEventListener("mouseleave",()=>hoverMapa(null));
  svg.addEventListener("mousedown",e=>e.target.dataset?.cod&&e.target.classList.add("press"));
  svg.addEventListener("pointerdown",e=>e.pointerType==="touch"&&hoverMapa(e.target.dataset?.cod||null,e));
  svg.addEventListener("mouseup",()=>svg.querySelectorAll(".press").forEach(x=>x.classList.remove("press")));
  /* links inversos: chips y burbujas iluminan su territorio en el mapa */
  document.addEventListener("mouseover",e=>{
    const chip=e.target.closest?.("#selinfo .chip");
    if(chip){const x=chip.querySelector("[data-c]");if(x)hoverMapa(x.dataset.c);return;}
    const card=e.target.closest?.(".resp[data-rid],.seat[data-rid]");
    if(card&&RESBY[card.dataset.rid])hoverMapa(RESBY[card.dataset.rid].dpto);
  });
  document.addEventListener("mouseout",e=>{
    if(e.target.closest?.("#selinfo .chip,.resp[data-rid],.seat[data-rid]"))hoverMapa(null);
  });
  paintNav();
}
function paintNav(){
  document.querySelectorAll("#navmap path").forEach(p=>{
    const c=p.dataset.cod;
    p.classList.toggle("sel",SEL.has(c)||(MODO==="pais"&&c===cur));
    p.classList.remove("fav","con","dep");
    if(DECIDIDO[c])p.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[DECIDIDO[c]]);
  });
  $("#maptag").textContent=MODO==="pais"?"el país responde":
