const SPRITES={};   // name → {size,palette,frames}
const UI={};        // copy_ui.json
const ASKC={};      // copy_ask.json
const FEEDT={start:"misión: {task}",plan:"plan listo: {n} tareas",
  shipped:"agente {ag} entrega {file}",jev_ok:"jev aprueba {id} ({p}%)",
  jev_fail:"jev rechaza {id} ({p}%)",done:"misión completa: {s}s · ${cost}"};

async function loadAssets(){
  const files={sp_worker:"sprites_worker.json",sp_states:"sprites_states.json",
    sp_main:"sprites_main.json",sp_staff:"sprites_staff.json",sp_icons:"sprites_icons.json",
    cp_ui:"copy_ui.json",cp_feed:"copy_feed.json",tk_palette:"palette.json",
    cp_ask:"copy_ask.json",local_keys:"local_keys.json"};
  await Promise.all(Object.entries(files).map(async([k,f])=>{
    try{
      const d=await (await fetch("assets/"+f)).json();
      if(k==="cp_ui") Object.assign(UI,d);
      else if(k==="cp_feed") Object.assign(FEEDT,d);
      else if(k==="cp_ask") Object.assign(ASKC,d);
      else if(k==="local_keys"){ if(!cfg.orkey&&d.openrouter) cfg.orkey=d.openrouter; }
      else if(k==="tk_palette") applyPalette(d);
      else if(validSprite(d)) SPRITES[k]=d;
    }catch(e){/* fallback ya cubre */}
  }));
  if(UI.title) $("#title").textContent=UI.title.toUpperCase();
  for(const [id,key] of [["#l-agents","agents_panel"],["#l-board","board_panel"],
    ["#l-inspector","inspector_panel"],["#l-budget","budget_panel"],
    ["#l-activity","activity_panel"],["#l-emptyhint","empty_hint"]])
    if(UI[key]) $(id).textContent=UI[key];
}
function validSprite(d){
  return d&&Array.isArray(d.frames)&&d.frames.length&&Array.isArray(d.palette)&&
    d.frames.every(f=>Array.isArray(f)&&f.length===d.size&&f.every(r=>Array.isArray(r)&&r.length===d.size));
}
function applyPalette(p){
  const map={bg:"--bg",panel:"--panel",grid:"--grid",text:"--text",text_dim:"--dim",
    working:"--work",ok:"--ok",fail:"--fail",accent:"--accent"};
  for(const k in map) if(p[k]) document.documentElement.style.setProperty(map[k],p[k]);
  if(Array.isArray(p.agents)) p.agents.forEach((c,i)=>{
    document.documentElement.style.setProperty("--a"+(i+1),c); AGCOLORS[i]=c;});
}

/* motor de sprites: canvas pixelado + animación por frames */
function drawFrame(cv,sp,fi,tint){
  const s=sp.size, ctx=cv.getContext("2d");
  ctx.clearRect(0,0,s,s);
  const fr=sp.frames[fi%sp.frames.length];
  for(let y=0;y<s;y++)for(let x=0;x<s;x++){
    const v=fr[y][x];
    if(!v) continue;
    ctx.fillStyle = tint&&v>=2? tint : (sp.palette[v]||"#fff");
    ctx.fillRect(x,y,1,1);
  }
}
function spriteCanvas(spKey,frames,tint,px){
  const sp=SPRITES[spKey]||FALLBACK;
  const cv=document.createElement("canvas");
  cv.width=cv.height=sp.size;
  cv.style.width=cv.style.height=(sp.size*(px||cfg.scale))+"px";
  cv.dataset.sp=spKey; cv.dataset.fr=JSON.stringify(frames); if(tint) cv.dataset.tint=tint;
  drawFrame(cv,sp,frames[0],tint);
  return cv;
}
let tick=0;
setInterval(()=>{ tick++;
  document.querySelectorAll("canvas[data-fr]").forEach(cv=>{
    const fr=JSON.parse(cv.dataset.fr);
    drawFrame(cv,SPRITES[cv.dataset.sp]||FALLBACK,fr[tick%fr.length],cv.dataset.tint);
  });
},420);

/* ═══ estado ═══ */
let runs={},curRun=null,timer=null;
let FABLE={visto:0,acto:null,usd:0};
function ingest(list){
  runs={};
  for(const r of list){
    if(r.run_id==null) continue;
    const run=runs[r.run_id]??={id:r.run_id,events:[],tasks:{},order:[],task:"",
      spent:null,done:false,t0:null,tEnd:null,jev:{},seconds:null,planMs:null};
    const p=r.payload||{}, _t=+new Date(r.ts), ts=Number.isFinite(_t)?_t:null;
    run.events.push({...r,ms:ts});
    if(ts!=null){run.t0=run.t0==null?ts:Math.min(run.t0,ts);
      run.tEnd=run.tEnd==null?ts:Math.max(run.tEnd,ts);}
    if(r.event==="start"&&p.task) run.task=p.task;
    if(r.event==="plan"&&Array.isArray(p.tasks)){p.tasks.forEach(t=>{if(!t||!t.id)return;run.tasks[t.id]={...t,status:"pending"};run.order.push(t.id)});
      run.task||=p.task||""; run.planMs=ts;}
    if(r.event==="shipped"&&r.task_id){const t=run.tasks[r.task_id]; if(t){t.status="ok";t.doneMs=ts;}}
    if(r.event==="jev"&&r.task_id){run.jev[r.task_id]=p.p;
      (run.jevlog??={})[r.task_id]??=[]; run.jevlog[r.task_id].push(p);
      if(p.p<0.5&&run.tasks[r.task_id])run.tasks[r.task_id].fixed=true;}
    if(r.event==="done"){run.done=true;run.spent=p.spent;run.seconds=p.seconds;}
    if(r.event&&r.event.startsWith("fable")){
      if(ts!=null&&ts>FABLE.visto)FABLE.visto=ts;  // solo tiempo real: sin ts no se renueva la marquesina
      if(r.event==="fable_inicio"&&p.acto)FABLE.acto=p.acto;
      if(r.event==="fable_costo"&&p.usd!=null)FABLE.usd=p.usd;
    }
  }
  for(const id in runs){const run=runs[id];
    run.order.forEach((tid,i)=>{run.tasks[tid].agent=i%8;});
    if(run.t0==null){let i=0;run.t0=0;run.events.forEach(e=>e.ms??=i++*1000);run.tEnd=run.events.length*1000;}
    else run.events.forEach((e,i)=>{if(e.ms==null)e.ms=run.events[i-1]?.ms??run.t0;});  /* mezcla ts/sin-ts: hereda el anterior, jamás NaN */
  }
}
async function fetchRows(){
  try{
    let list;
    if(cfg.src==="local") list=await (await fetch("feed.json?x="+Date.now())).json();
    else{list=await (await fetch(cfg.url+"/rest/v1/army_events?select=*&order=id.desc&limit=2000",
      {headers:{apikey:cfg.key}})).json();
      if(!Array.isArray(list)) throw 0;}
    /* orden estable por fila: ts si parsea, si no id; desempate por id (dentro
       del mismo segundo Supabase venía id.desc y 'done' salía antes que 'shipped') */
    list.forEach((r,i)=>{const t=Date.parse(r.ts);r._k=Number.isFinite(t)?t:(Number.isFinite(+r.id)?+r.id:i);});
    list.sort((a,b)=>a._k-b._k||((+a.id||0)-(+b.id||0)));
    ingest(list); render(); lamp(true);
  }catch(e){lamp(false);}
}
function lamp(on){$("#lamp").classList.toggle("on",on);
  $("#lamptxt").textContent=on?(UI.live||"LIVE"):(UI.offline||"OFFLINE");}

