function fmtT(ms,t0){const s=Math.max(0,(ms-t0)/1000);return s>=60?(s/60).toFixed(1)+"m":s.toFixed(0)+"s";}
function tpl(str,vars){return str.replace(/\{(\w+)\}/g,(_,k)=>vars[k]??"");}

