    const key=t?"sp_worker":run.done?"sp_states":"sp_worker";
    const fr=t?[2,3,4,5]:run.done?[0,1,2,3]:[0,1];
    div.append(spriteCanvas(key,fr,null,2.5));
    div.insertAdjacentHTML("beforeend",
      `<div class="nm">agente ${i+1}<i>${t?"■ "+esc(tid):run.done?"✓":"·"}</i></div>
       <div class="tk">${t? esc(t.filename||t.prompt?.slice(0,70)||tid) :
         run.done?(UI.done_all||"misión completa"):(UI.idle||"en espera")}</div>`);
    g.append(div);
  }
  $("#agcount").textContent=busyN? busyN+" trabajando":"";

  /* stats del día */
  let ds=0,or_=0,tasksAll=0,jevAll=[],runsDone=0;
  ids.forEach(i=>{const r=runs[i];
    if(r.spent){ds+=r.spent.deepseek||0;or_+=r.spent.openrouter||0;}
    if(r.done)runsDone++;
    tasksAll+=r.order.filter(id=>r.tasks[id].status==="ok").length;
    jevAll.push(...Object.values(r.jev));});
  const jevAvg=jevAll.length?(jevAll.reduce((a,b)=>a+b,0)/jevAll.length*100).toFixed(0):"—";
  $("#stats").innerHTML=[["misiones",runsDone+"/"+ids.length],["entregas",tasksAll],
    ["aprobación jev",jevAvg+"%"],["gasto",("$"+(ds+or_).toFixed(3))]]
    .map(([k,v])=>`<div class="stat"><div class="v">${v}</div><div class="k">${k}</div></div>`).join("");

  /* inspector */
  const st=$("#stamps"); st.innerHTML="";
  run.order.filter(id=>run.jev[id]!=null).forEach(id=>{
    const p=run.jev[id],cls=p>=.85?"hi":p>=.5?"mid":"lo";
    const row=document.createElement("div"); row.className="jrow";
    if(SPRITES.sp_icons) row.append(spriteCanvas("sp_icons",[p>=.5?1:2],null,2));
    row.insertAdjacentHTML("beforeend",`<span class="f">${esc(run.tasks[id]?.filename||id)}</span>
