      return `<div class="brow" style="--agc:var(${col})"><div class="l"><span>${n}</span><b>$${v.toFixed(3)} / $${c}</b></div>
      <div class="bricks">${Array.from({length:20},(_,i)=>`<i class="${i<filled?"f":""}"></i>`).join("")}</div></div>`;
    }).join("")
    +`<div class="brow"><div class="l"><span>anthropic</span><b>$100 · reservado</b></div></div>`;

  drawBoard(run,runningIds);
  drawFeed(run);
}

/* tablero: barras por agente + rutas Manhattan */
function drawBoard(run,runningIds){
  runningIds??=run.done?[]:run.order.filter(id=>{const t=run.tasks[id];
    return t.status!=="ok"&&(t.deps||[]).every(d=>run.tasks[d]?.status==="ok");});
  const svg=$("#ops"),W=svg.clientWidth||800,H=svg.clientHeight||460;
  const n=run.order.length; if(!n){svg.innerHTML="";return;}
  const t0=run.planMs??run.t0,tE=Math.max(run.tEnd,t0+1000);
  const padL=14,padR=170,padT=14,padB=22;
  const rowH=Math.min(40,(H-padT-padB)/n);
  const X=ms=>padL+((ms??tE)-t0)/(tE-t0)*(W-padL-padR);
  let g="";
  const span=(tE-t0)/1000,step=span>120?60:span>40?20:span>12?5:2;
  for(let s=0;s<=span;s+=step){const x=X(t0+s*1000);
    g+=`<line class="axis" x1="${x}" y1="${padT}" x2="${x}" y2="${H-padB}"/>
        <text class="axist" x="${x+4}" y="${H-8}">${s>=60?(s/60)+"m":s+"s"}</text>`;}
  const pos={};
  run.order.forEach((id,i)=>pos[id]={y:padT+i*rowH+rowH/2});
  const startX=id=>{const t=run.tasks[id],deps=t.deps||[];
    return X(deps.length?Math.max(...deps.map(d=>run.tasks[d]?.doneMs??run.planMs??run.t0)):run.planMs??run.t0);};
  /* rutas Manhattan concretas, color del agente origen */
  run.order.forEach(id=>{
    (run.tasks[id].deps||[]).forEach(d=>{
      const a=pos[d],b=pos[id]; if(!a||!b)return;
      const x1=X(run.tasks[d].doneMs),x2=startX(id),xm=x1+6;
      g+=`<path class="dep" stroke="${AGCOLORS[run.tasks[d].agent]}"
          d="M${x1},${a.y} H${xm} V${b.y} H${x2}"/>`;});
  });
  run.order.forEach(id=>{
    const t=run.tasks[id],y=pos[id].y,col=AGCOLORS[t.agent];
    const x1=startX(id),x2=t.doneMs?X(t.doneMs):X(tE);
    const w=Math.max(6,x2-x1),h=Math.min(18,rowH-8);
    const running=runningIds.includes(id);
    const fill=t.status==="ok"?col:running?col:"none";
    const op=t.status==="ok"?".9":running?".45":"0";
    g+=`<rect class="bar ${running?"running":""}" data-tid="${esc(id)}" x="${x1}" y="${y-h/2}"
        width="${w}" height="${h}" fill="${fill}" fill-opacity="${op}"
        stroke="${t.status==="ok"||running?col:"var(--grid)"}"
        ${t.fixed?'stroke-dasharray="5 2"':""}/>`;
    g+=`<text class="bnum" x="${x1+4}" y="${y+3}" fill="${t.status==="ok"?"var(--bg)":col}">A${t.agent+1}</text>`;
    g+=`<text class="blabel" x="${x2+8}" y="${y+1}" fill="${col}">${esc(id)}</text>
        <text class="bfile" x="${x2+8}" y="${y+12}">${esc(t.filename||"")}</text>`;
  });
  svg.setAttribute("viewBox",`0 0 ${W} ${H}`);
  svg.innerHTML=g;
}

function drawFeed(run){
  const el=$("#feedin"),t0=run.planMs??run.t0;
  const firma=run.id+":"+run.events.length;
  if(el.dataset.firma===firma) return;      /* nada nuevo: no tocar el scroll */
  el.dataset.firma=firma;
  const st=el.scrollTop;
  el.innerHTML=[...run.events].reverse().map(e=>{
    const p=e.payload||{},t=run.tasks[e.task_id]||{};
    let key=e.event,cls="wk";
    if(e.event==="shipped"){cls="ok"}
    if(e.event==="jev"){key=p.p>=.5?"jev_ok":"jev_fail";cls=p.p>=.5?"ok":"bd";}
    if(e.event==="done")cls="ok";
    if(e.event&&e.event.startsWith("fable")){
      const pl=e.payload||{};
      const txt=e.event==="fable_inicio"?"🧠 FABLE 5.1 · "+(pl.acto||"trabajando"):
        e.event==="fable_costo"?("FABLE gasto: $"+pl.usd+" · caché "+((pl.cache_read||0).toLocaleString())+" tk"):
        e.event==="fable_duelo"?("⚔️ DUELO: enjambre "+(pl.marcador?.enjambre??"?")+" — "+(pl.marcador?.fable??"?")+" fable"):
        e.event;
      return `<div class="l"><time class="num">·</time><span class="ev fable">${esc(txt)}</span></div>`;
    }
    const str=FEEDT[key]; if(!str)return "";
    const txt=tpl(str,{task:(p.task||"").slice(0,60),n:p.tasks?.length,id:e.task_id,
      file:t.filename||(p.chars!=null?p.chars+" chars":e.task_id||""),p:p.p!=null?(p.p*100).toFixed(0):"",
      s:p.seconds,cost:p.spent?(p.spent.deepseek+p.spent.openrouter).toFixed(4):"",
      ag:t.agent!=null?t.agent+1:"?"});
    return `<div class="l"><time>+${fmtT(e.ms,t0)}</time><span class="ev ${cls}">${esc(txt)}</span></div>`;
  }).join("");
  el.scrollTop=st;
}

