function openTask(tid){
  const run=runs[curRun]; if(!run)return;
  const t=run.tasks[tid]; if(!t)return;
  const t0=run.planMs??run.t0, col=AGCOLORS[t.agent];
  const jl=(run.jevlog?.[tid])||[];
  const jevHtml=jl.map((j,i)=>{
    const cls=j.p>=.85?"var(--ok)":j.p>=.5?"var(--work)":"var(--fail)";
    const diag=j.diag?Object.entries(j.diag).filter(([,v])=>v<.5).map(([k])=>k).join(", "):"";
    return `<div class="jv"><span class="p" style="color:${cls}">${(j.p*100).toFixed(0)}%</span>
      <span>calidad ${j.quality?.toFixed(1)??"—"}/4</span>
      <span>→ ${ACTNAMES[j.action]||j.action||"aprobar"}</span>
      ${diag?`<span class="diag">falló: ${esc(diag)}</span>`:""}</div>`;
  }).join("")||`<div class="jv"><span class="diag">sin inspecciones</span></div>`;
  openModal(tid+" · agente "+(t.agent+1),`
    <div class="kv">
      <b>estado</b><span style="color:${t.status==="ok"?"var(--ok)":col}">${t.status==="ok"?"entregada":"en curso"}${t.fixed?" (con fixes)":""}</span>
      <b>agente</b><span style="color:${col}">agente ${t.agent+1} · deepseek-flash</span>
      <b>thinking</b><span>${esc(t.thinking||"none")}</span>
      <b>archivo</b><span>${esc(t.filename||tid+".md")}</span>
      <b>depende de</b><span>${(t.deps||[]).map(d=>`<a href="#" onclick="openTask('${esc(d)}');return false" style="color:${AGCOLORS[run.tasks[d]?.agent??0]}">${esc(d)}</a>`).join(" · ")||"nada — arranca de una"}</span>
      <b>entregada en</b><span>${t.doneMs?fmtT(t.doneMs,t0):"—"}</span>
    </div>
    <div><b style="font-family:Silkscreen;font-size:9px;color:var(--faint)">ORDEN RECIBIDA</b>
    <div class="prompt">${esc(t.prompt||"—")}</div></div>
    <div><b style="font-family:Silkscreen;font-size:9px;color:var(--faint)">INSPECCIONES JEV</b>${jevHtml}</div>`);
}
function openAgent(i){
  const run=runs[curRun]; if(!run)return;
  const mine=run.order.filter(id=>run.tasks[id].agent===i);
  if(!mine.length){openModal("agente "+(i+1),`<div class="kv"><b>estado</b><span>en espera — sin tareas en esta misión</span></div>`);return;}
  openModal("agente "+(i+1)+" · deepseek-flash",
    mine.map(id=>{const t=run.tasks[id],p=run.jev[id];
      return `<div class="jv" style="cursor:pointer" onclick="openTask('${esc(id)}')">
        <span class="p" style="color:${AGCOLORS[i]}">${esc(id)}</span>
        <span>${esc(t.filename||"")}</span>
        <span style="margin-left:auto;color:${t.status==="ok"?"var(--ok)":"var(--work)"}">${t.status==="ok"?"entregada":"en curso"}</span>
        ${p!=null?`<span class="p">${(p*100).toFixed(0)}%</span>`:""}</div>`;}).join(""));
}
$("#ops").addEventListener("click",e=>{const tid=e.target.dataset?.tid; if(tid)openTask(tid);});

/* ═══ pregúntale al visor: chat agéntico sobre el estado real ═══ */
const askHist=[];
function askContext(){
  const ids=Object.keys(runs).sort().reverse(), run=runs[curRun];
  if(!run) return "Sin corridas todavía.";
  const t0=run.planMs??run.t0;
  const tasks=run.order.map(id=>{const t=run.tasks[id];
    return {id,agente:(t.agent??0)+1,estado:t.status==="ok"?"entregada":"en curso",
      archivo:t.filename||null,thinking:t.thinking||"none",deps:t.deps||[],
      jev:run.jev[id]!=null?Math.round(run.jev[id]*100)+"%":null,
      seg:t.doneMs?Math.round((t.doneMs-t0)/1000):null};});
  let ds=0,or_=0;ids.forEach(i=>{const s=runs[i].spent;if(s){ds+=s.deepseek||0;or_+=s.openrouter||0;}});
  return JSON.stringify({
    mision:run.task, corrida:curRun, completada:run.done,
    duracion_seg:run.seconds, tareas:tasks,
    corridas_de_hoy:ids.length, gasto_hoy_usd:{deepseek:+ds.toFixed(4),openrouter:+or_.toFixed(4)},
    arquitectura:"agente principal (deepseek-v4-pro o Fable 5.1) planifica el DAG; 8 agentes deepseek-flash ejecutan en paralelo con thinking por tarea; el inspector Jev (typesafe/jev-1.13) revisa cada entrega y enruta reintentos; un ensamblador une el resultado final",
  });
}
function addMsg(cls,txt){
  const d=document.createElement("div");d.className=cls;d.textContent=txt;
  $("#askmsgs").append(d);$("#askmsgs").scrollTop=1e9;return d;
}
async function ask(q){
  if(!q.trim())return;
  if(!cfg.orkey){addMsg("a",ASKC.nokey||"pega tu key de openrouter en ajustes para chatear");return;}
  addMsg("q",q); askHist.push({role:"user",content:q});
  const a=addMsg("a thinking",ASKC.thinking||"consultando…");
  try{
    const r=await fetch("https://openrouter.ai/api/v1/chat/completions",{
      method:"POST",
      headers:{Authorization:"Bearer "+cfg.orkey,"Content-Type":"application/json"},
      body:JSON.stringify({model:"deepseek/deepseek-v4.1-flash",stream:true,max_tokens:400,
        reasoning:{enabled:false},
        messages:[{role:"system",content:
          "Eres el visor de un enjambre de agentes. Responde en español, corto y "+
          "concreto (máx 4 líneas), SOLO con los datos del estado adjunto; si algo "+
          "no está en los datos, dilo sin inventar. Estado actual:\n"+askContext()},
          ...askHist.slice(-6)]}),
    });
    if(!r.ok) throw new Error("HTTP "+r.status);
    a.classList.remove("thinking"); a.textContent="";
    const rd=r.body.getReader(), dec=new TextDecoder(); let buf="",full="";
    for(;;){
      const {done,value}=await rd.read(); if(done)break;
      buf+=dec.decode(value,{stream:true});
      for(const line of buf.split("\n")){
        if(!line.startsWith("data: ")||line.includes("[DONE]"))continue;
        try{const tok=JSON.parse(line.slice(6)).choices?.[0]?.delta?.content;
          if(tok){full+=tok;a.textContent=full;$("#askmsgs").scrollTop=1e9;}}catch(e){}
      }
      buf=buf.slice(buf.lastIndexOf("\n")+1);
    }
    askHist.push({role:"assistant",content:full});
  }catch(e){a.classList.remove("thinking");a.textContent="sin respuesta ("+e.message+")";}
}
$("#askbar").onsubmit=e=>{e.preventDefault();const v=$("#askin").value;$("#askin").value="";ask(v);};
function renderSugg(){
  const s=ASKC.suggestions||["¿qué hace el agente 3?","¿cómo va la misión?",
    "¿qué rechazó jev y por qué?","¿cuánto hemos gastado hoy?"];
  $("#sugg").innerHTML=s.slice(0,4).map(x=>`<button type="button">${esc(x)}</button>`).join("");
  $("#sugg").querySelectorAll("button").forEach(b=>b.onclick=()=>ask(b.textContent));
}
$("#c-orkey").onchange=e=>{cfg.orkey=e.target.value.trim();save();};

loadAssets().then(()=>{
  if(ASKC.panel) $("#l-ask").textContent=ASKC.panel;
  if(ASKC.placeholder) $("#askin").placeholder=ASKC.placeholder;
  $("#c-orkey").value=cfg.orkey;
  renderSugg();
  applyCfg();   // arranca el timer de refresco (hallazgo del bug-hunt)
  fetchRows();
});
</script>
</body>
