  <section id="censo">
    <div class="panel"><h2>colombia <b id="maptag">toca un territorio</b></h2>
      <div id="navmap" aria-busy="true"><div id="maptip"></div><div class="pxf" style="color:var(--faint);padding:24px;text-align:center">cargando 33 territorios…</div></div><div id="maplabel">—</div>
    </div>
