#modal .prompt{background:var(--panel2); border:2px solid var(--grid); padding:9px 11px;
  font-size:12px; line-height:1.5; color:var(--dim); white-space:pre-wrap}
#modal .jv{display:flex; gap:10px; align-items:baseline; font-size:11.5px;
