#modal .jv .p{font-family:"Silkscreen"; font-size:10px}
#modal .jv .diag{color:var(--faint)}
.bar.running{animation:barpulse 1.1s steps(2) infinite}
@keyframes barpulse{50%{fill-opacity:.75}}
.bar,.ag,.staffc{cursor:pointer}

/* ── config ── */
#cfg{position:fixed; top:54px; right:8px; width:290px; z-index:9; background:var(--panel);
  border:var(--px) solid var(--grid); padding:14px; display:none; box-shadow:6px 6px 0 #000a}
#cfg.open{display:block}
#cfg label{display:block; font-family:"Silkscreen"; font-size:8px; color:var(--faint); margin:10px 0 4px}
