/* ═══ modal de detalle: qué hace cada tarea/agente ═══ */
const ACTNAMES={aprobar:"aprobar",fix_con_feedback:"fix con feedback",
  reintentar_pensando_mas:"reintentar pensando más",escalar_a_modelo_pro:"escalar a modelo pro"};
